import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import { t } from '../util';

/**
 * What the dossier's windows share: a form of fields, a Save button, and a
 * save that goes through the page (which then shows the new dossier) and
 * reports errors in the window.
 */
export default class DossierModal extends FormModal {
  className() {
    return 'DossierModal Modal--medium';
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form"
    }, this.fields(), m("div", {
      className: "Form-group DossierModal-actions"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary",
      loading: this.loading
    }, t('modals.save')))));
  }

  /** A labelled field; `input` is given the id the label points at. */
  field(name, label, input, help) {
    const id = `dossier-${name}`;
    input.attrs = {
      id,
      name,
      ...input.attrs
    };
    return m("div", {
      className: `Form-group DossierModal-field DossierModal-field--${name}`
    }, m("label", {
      htmlFor: id
    }, label), input, help ? m("p", {
      className: "helpText"
    }, help) : null);
  }

  /** A text input bound to this.values[name]. */
  text(name, attrs = {}) {
    return m("input", Object.assign({
      className: "FormControl",
      type: "text",
      value: this.values[name] ?? '',
      oninput: e => this.values[name] = e.target.value
    }, attrs));
  }
  textarea(name, attrs = {}) {
    return m("textarea", Object.assign({
      className: "FormControl",
      rows: "4",
      value: this.values[name] ?? '',
      oninput: e => this.values[name] = e.target.value
    }, attrs));
  }

  /** A native select (works with every screen reader and phone picker). */
  select(name, options, attrs = {}) {
    return m("select", Object.assign({
      className: "FormControl",
      value: this.values[name] ?? '',
      onchange: e => this.values[name] = e.target.value
    }, attrs), Object.entries(options).map(([value, label]) => m("option", {
      value: value
    }, label)));
  }
  run(method, path, body) {
    this.loading = true;
    this.alertAttrs = null;
    return this.attrs.page.save(method, path, body, {
      errorHandler: this.onerror.bind(this)
    }).then(response => {
      this.loading = false;
      return response;
    }).catch(error => {
      this.loading = false;
      m.redraw();
      throw error;
    });
  }
}
flarum.reg.add('ernestdefoe-dossier', 'forum/modals/DossierModal', DossierModal);